Item.method_code:
const { item, itemNode, itemTypeName } = options;
if (!item && !itemNode) {
	return false;
}
const id = item ? item.id : itemNode.getAttribute('id');
const isNew = ArasModules.item.isNew(itemTypeName, id);

	if (isNew) {
		return false;
	}
const isEditMode = ArasModules.item.isEditState(itemTypeName, id);

if (isEditMode) {
	const isClaimed = ArasModules.item.isEditedAndClaimed(itemTypeName, id);
	return !isClaimed;
}

const lockItemCommand = commands.commandFactory('LockItem', options);
return lockItemCommand.canExecute();
